'use strict';
// Interactive front-end for the versioned admin checklist builder.
const cloneTemplateValue=value=>JSON.parse(JSON.stringify(value));
let builderSelected=null,builderSection=0,builderTab='structure',customSection=0;
function initTemplateData(){if(!data.templates){data.templates=[{id:'fded-v1',family:'fded',version:1,name:'FDED site survey checklist',published:true,definition:cloneTemplateValue(window.FDED_TEMPLATE),clients:[{name:'Nokia',logo:'assets/nokia.png'},{name:'TAWAL',logo:'assets/tawal.png'}]}];data.projectTemplates={'Telecom survey':'fded-v1','Network expansion':'fded-v1'};persist()}if(!builderSelected||!data.templates.some(t=>t.id===builderSelected))builderSelected=data.templates[0]?.id}
function currentTemplate(){initTemplateData();return data.templates.find(t=>t.id===builderSelected)}
function fieldCount(t){return t.definition.sections.reduce((n,s)=>n+s.fields.length,0)}
function fixedCount(t){return t.definition.sections.reduce((n,s)=>n+s.fields.filter(f=>f.excel_row).length,0)}
function clientLogos(clients){return `<div class="client-branding">${(clients||[]).filter(c=>c.name||c.logo).map(c=>`<div>${c.logo?`<img src="${E(c.logo)}" alt="${E(c.name)}">`:''}<span>${E(c.name)}</span></div>`).join('')}</div>`}
function builderPage(){initTemplateData();if(role!=='Admin')return `<section class="card"><div class="empty">${I('shield')}Checklist templates are managed by the Admin.<br><button class="btn primary" style="margin-top:18px" onclick="changeRole('Admin');go('builder')">Explore Admin</button></div></section>`;const t=currentTemplate();builderSection=Math.max(0,Math.min(builderSection,t.definition.sections.length-1));const sec=t.definition.sections[builderSection];return `${title('Your checklist. Your client.','Create the form your project needs. Keep the survey and approval workflow.',`<button class="btn" onclick="newChecklistTemplate(true)">${I('plus')}Blank checklist</button><button class="btn primary" onclick="newChecklistTemplate(false)">${I('clipboard')}Copy original FDED</button>`)}<div class="builder-workspace"><aside class="card template-library"><div class="card-head"><h3>Checklist templates</h3></div>${data.templates.map(x=>`<button class="template-library-item ${x.id===t.id?'active':''}" onclick="builderSelected='${E(x.id)}';builderSection=0;render()"><strong>${E(x.name)}</strong><small>v${x.version} · ${x.published?'Published':'Draft'} · ${fieldCount(x)} fields</small></button>`).join('')}<div class="builder-note">${I('shield')}Existing surveys keep their assigned template revision and client logos.</div></aside><div><section class="card"><div class="card-head"><div><h2>${E(t.name)}</h2><p>Revision ${t.version} · ${t.definition.sections.length} sections · ${fieldCount(t)} fields${fixedCount(t)?' · '+fixedCount(t)+' original fixed rows':''}</p></div><span class="tag ${t.published?'green':'orange'}">${t.published?'Published · locked':'Editable draft'}</span></div><div class="builder-toolbar"><div class="panel-tabs">${[['structure','Sections & fields'],['branding','Client logos'],['assignment','Assign to project']].map(([k,n])=>`<button class="${builderTab===k?'active':''}" onclick="builderTab='${k}';render()">${n}</button>`).join('')}</div><button class="btn" onclick="duplicateChecklistTemplate()">${I('file')}${t.published?'Edit as new revision':'Duplicate draft'}</button></div><div class="form-body">${builderTab==='structure'?builderStructure(t,sec):builderTab==='branding'?builderBranding(t):builderAssignment(t)}</div><div class="form-foot"><span class="small muted">${t.published?'Published revisions protect existing survey records.':'Draft changes save on this device as you edit.'}</span><div class="row">${t.published?`<button class="btn" onclick="tryTemplate()">Try sample survey ${I('arrow')}</button>`:`<button class="btn" onclick="saveTemplateDraft()">Save draft</button><button class="btn primary" onclick="publishTemplate()">Publish revision ${I('check')}</button>`}</div></div></section><div class="builder-workflow"><span>${I('users')}Assign site</span><span>→</span><span>${I('clipboard')}Survey</span><span>→</span><span>${I('camera')}Evidence</span><span>→</span><span>${I('shield')}Review & approval</span></div></div></div>`}
function builderStructure(t,sec){if(!sec)return `<div class="empty">No sections in this draft yet.<br><button class="btn primary" style="margin-top:20px" onclick="addBuilderSection()">Add first section</button></div>`;return `<div class="row between wrap" style="margin-bottom:20px"><div class="field grow"><label for="builder-section">Choose a section to edit</label><select id="builder-section" onchange="builderSection=Number(this.value);render()">${t.definition.sections.map((s,i)=>`<option value="${i}" ${i===builderSection?'selected':''}>${i+1}. ${E(s.group?s.group+' / ':'')}${E(s.title)} (${s.fields.length})</option>`).join('')}</select></div>${t.published?'':`<button class="btn" style="margin-top:19px" onclick="addBuilderSection()">${I('plus')}Add section</button>`}</div><div class="builder-section-header"><div><h3>${E(sec?.title||'No sections yet')}</h3><p class="small muted" style="margin-top:5px">${E(sec?.group||'Checklist section')}</p></div>${t.published?'':`<div class="row"><button class="iconbtn" aria-label="Move section up" onclick="moveBuilderSection(-1)">↑</button><button class="iconbtn" aria-label="Move section down" onclick="moveBuilderSection(1)">↓</button><button class="btn link" onclick="renameBuilderSection()">Edit section</button><button class="btn link danger" onclick="removeBuilderSection()">Remove</button></div>`}</div><div class="builder-field-list">${(sec?.fields||[]).map((f,i)=>`<div class="builder-field-row"><span class="builder-order">${i+1}</span><div class="grow"><strong>${E(f.label)}</strong><div class="row" style="gap:7px;margin-top:6px"><span class="tag gray">${E(f.type)}</span>${f.required?'<span class="builder-required">Required</span>':'<span class="small muted">Optional</span>'}${f.unit?`<span class="small muted">${E(f.unit)}</span>`:''}${f.type==='select'?`<span class="small muted">${E((f.options||[]).join(' / '))}</span>`:''}</div></div>${t.published?'':`<button class="iconbtn" aria-label="Move field up" onclick="moveBuilderField(${i},-1)">↑</button><button class="iconbtn" aria-label="Move field down" onclick="moveBuilderField(${i},1)">↓</button><button class="btn link" onclick="editBuilderField(${i})">Edit</button><button class="iconbtn" aria-label="Remove field" onclick="removeBuilderField(${i})">${I('trash')}</button>`}</div>`).join('')||'<div class="empty">Add a field to this section.</div>'}</div>${t.published?'':`<button class="btn" style="margin-top:19px" onclick="editBuilderField(-1)">${I('plus')}Add field</button>`}`}
function builderBranding(t){return `<div class="field" style="margin-bottom:25px"><label for="checklist-name">Checklist name</label><input id="checklist-name" value="${E(t.name)}" ${t.published?'readonly':''} oninput="changeTemplateName(this.value)"></div><h3>Client logos</h3><p class="form-intro">Nokia and TAWAL are the original clients. Replace the names and logos for any client or project.</p><div class="builder-logo-grid">${t.clients.map((c,i)=>`<div class="builder-logo-card"><div class="builder-logo-display">${c.logo?`<img src="${E(c.logo)}" alt="${E(c.name)}">`:`<span>${E(c.name)||'Client logo'}</span>`}</div><div class="field"><label for="client-name-${i}">${i===0?'Left':'Right'} client name</label><input id="client-name-${i}" value="${E(c.name)}" ${t.published?'readonly':''} oninput="changeClientName(${i},this.value)"></div>${t.published?'':`<label class="btn" style="margin-top:16px">${I('upload')}Replace logo<input type="file" accept="image/png,image/jpeg,image/webp" hidden onchange="uploadClientLogo(${i},this)"></label><button class="btn link danger" style="margin:12px 0 0 8px" onclick="removeClientLogo(${i})">Remove logo</button>`}</div>`).join('')}</div><div class="builder-brand-preview"><span class="eyebrow muted">REPORT HEADER PREVIEW</span>${clientLogos(t.clients)}<strong>${E(t.name)}</strong></div>`}
function builderAssignment(t){return `<h3>Use this revision for new surveys</h3><p class="form-intro">Publish the checklist, then assign it to a project. Existing surveys retain the questions, field types, and logos they started with.</p>${['Telecom survey','Network expansion'].map(p=>{const x=data.templates.find(q=>q.id===data.projectTemplates[p]);return `<div class="builder-project-row"><span class="workspace-icon">${I('folder')}</span><div class="grow"><strong>${p}</strong><small>${x?E(x.name)+' · v'+x.version:'No assigned custom checklist'}</small></div><button class="btn ${data.projectTemplates[p]===t.id?'primary':''}" ${!t.published?'disabled':''} onclick="assignChecklistTemplate('${p}')">${data.projectTemplates[p]===t.id?'Assigned':'Assign revision'}</button></div>`}).join('')}${!t.published?'<p class="small muted" style="margin-top:20px">Publish this draft before assigning it.</p>':''}`}
function canEditTemplate(){return role==='Admin'&&!currentTemplate().published}
function newChecklistTemplate(blank){if(role!=='Admin')return;const id='tpl-'+crypto.randomUUID();const def=blank?{title:'Custom checklist',sections:[{id:'general',title:'General information',fields:[{id:'site_id',label:'Site ID',type:'text',system:'site_id',required:true}]}]}:cloneTemplateValue(window.FDED_TEMPLATE);data.templates.push({id,family:id,version:1,name:def.title,published:false,definition:def,clients:[{name:'Nokia',logo:'assets/nokia.png'},{name:'TAWAL',logo:'assets/tawal.png'}]});builderSelected=id;builderSection=0;builderTab='structure';persist();go('builder');toast(blank?'Blank checklist created':'All original checklist rows copied to a new draft')}
function duplicateChecklistTemplate(){if(role!=='Admin')return;const t=currentTemplate(),next=Math.max(...data.templates.filter(x=>x.family===t.family).map(x=>x.version))+1;const copy=cloneTemplateValue(t);copy.id='tpl-'+crypto.randomUUID();copy.version=next;copy.published=false;data.templates.push(copy);builderSelected=copy.id;persist();render();toast('New draft revision created. Existing surveys stay unchanged.')}
function changeTemplateName(v){if(!canEditTemplate())return;currentTemplate().name=v.slice(0,160);currentTemplate().definition.title=v.slice(0,160);persist()}
function changeClientName(i,v){if(!canEditTemplate())return;currentTemplate().clients[i].name=v.slice(0,80);persist()}
async function uploadClientLogo(i,input){if(!canEditTemplate()||!input.files[0])return;const file=input.files[0];if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){toast('Choose a PNG, JPG, or WebP logo smaller than 2 MB');return}const src=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>resolve(null);r.readAsDataURL(file)});if(!src)return;const t=currentTemplate(),before=t.clients[i].logo;t.clients[i].logo=src;if(!persist())t.clients[i].logo=before;render()}
function removeClientLogo(i){if(!canEditTemplate())return;currentTemplate().clients[i].logo='';persist();render()}
function saveTemplateDraft(){if(!canEditTemplate())return;if(persist())toast('Checklist draft saved')}
function templateProblems(t){const errors=[],ids=new Set();if(!t.name.trim())errors.push('Checklist name');if(!t.definition.sections.length)errors.push('At least one section');for(const s of t.definition.sections){if(!s.title.trim())errors.push('Section name');if(!s.fields.length)errors.push(s.title+': add at least one field');for(const f of s.fields){if(!f.label.trim())errors.push('Field label');if(f.system&&(f.system!=='site_id'||f.type!=='text'))errors.push('Linked Site ID must remain a text field');if(ids.has(f.id))errors.push('Duplicate field ID');ids.add(f.id);if(f.type==='select'&&!f.options?.length)errors.push(f.label+': dropdown choices');if(f.type==='table'&&!f.columns?.length)errors.push(f.label+': table columns')}}return errors}
function publishTemplate(){if(!canEditTemplate())return;const t=currentTemplate(),errors=templateProblems(t);if(errors.length){toast('Complete: '+errors.slice(0,3).join(', '));return}t.published=true;if(!persist()){t.published=false;return}builderTab='assignment';render();toast('Revision published. Assign it to the required project.')}
function assignChecklistTemplate(project){const t=currentTemplate();if(role!=='Admin'||!t.published)return;data.projectTemplates[project]=t.id;persist();render();toast('New surveys in '+project+' will use revision '+t.version)}
function renameBuilderSection(){if(!canEditTemplate())return;const s=currentTemplate().definition.sections[builderSection];showModal('Edit section',`<div class="field"><label for="section-title">Section name</label><input id="section-title" value="${E(s.title)}" maxlength="160"></div><div class="field"><label for="section-group">Group / parent heading (optional)</label><input id="section-group" value="${E(s.group||'')}" maxlength="160"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="commitBuilderSection()">Save section</button>`)}
function addBuilderSection(){if(!canEditTemplate())return;showModal('Add section',`<div class="field"><label for="section-title">Section name</label><input id="section-title" placeholder="e.g. Foundation investigation" maxlength="160"></div><div class="field"><label for="section-group">Group / parent heading (optional)</label><input id="section-group" maxlength="160"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="commitBuilderSection(true)">Add section</button>`)}
function commitBuilderSection(add=false){if(!canEditTemplate())return;const title=document.getElementById('section-title').value.trim(),group=document.getElementById('section-group').value.trim();if(!title){toast('Enter a section name');return}if(add){currentTemplate().definition.sections.push({id:'section_'+crypto.randomUUID().replaceAll('-','').slice(0,12),title,group,fields:[]});builderSection=currentTemplate().definition.sections.length-1}else Object.assign(currentTemplate().definition.sections[builderSection],{title,group});persist();closeModal();render()}
function removeBuilderSection(){if(!canEditTemplate())return;const s=currentTemplate().definition.sections[builderSection];showModal('Remove this section?',`<p>Remove <strong>${E(s.title)}</strong> and its ${s.fields.length} fields from this draft? Existing surveys keep their previous checklist.</p>`,`<button class="btn" onclick="closeModal()">Keep section</button><button class="btn danger" onclick="confirmRemoveBuilderSection()">Remove section</button>`)}
function confirmRemoveBuilderSection(){if(!canEditTemplate())return;currentTemplate().definition.sections.splice(builderSection,1);builderSection=Math.max(0,builderSection-1);persist();closeModal();render()}
function moveInArray(a,i,delta){const j=i+delta;if(j>=0&&j<a.length)[a[i],a[j]]=[a[j],a[i]]}
function moveBuilderSection(delta){if(!canEditTemplate())return;const a=currentTemplate().definition.sections,j=builderSection+delta;if(j<0||j>=a.length)return;moveInArray(a,builderSection,delta);builderSection=j;persist();render()}
function moveBuilderField(i,delta){if(!canEditTemplate())return;moveInArray(currentTemplate().definition.sections[builderSection].fields,i,delta);persist();render()}
function removeBuilderField(i){if(!canEditTemplate())return;const s=currentTemplate().definition.sections[builderSection];showModal('Remove this field?',`<p>${E(s.fields[i].label)}</p><p>Only this draft changes. Previously assigned surveys retain their original field.</p>`,`<button class="btn" onclick="closeModal()">Keep field</button><button class="btn danger" onclick="confirmRemoveBuilderField(${i})">Remove field</button>`)}
function confirmRemoveBuilderField(i){if(!canEditTemplate())return;currentTemplate().definition.sections[builderSection].fields.splice(i,1);persist();closeModal();render()}
function editBuilderField(i){if(!canEditTemplate())return;const f=i<0?{label:'',type:'text',required:false}:currentTemplate().definition.sections[builderSection].fields[i];showModal(i<0?'Add checklist field':'Edit checklist field',`<div class="field"><label for="field-label">Question / field label</label><textarea id="field-label" maxlength="3000">${E(f.label)}</textarea></div><div class="fieldgrid"><div class="field"><label for="field-type">Field type</label><select id="field-type" onchange="document.getElementById('field-options-wrap').hidden=this.value!=='select';document.getElementById('field-columns-wrap').hidden=this.value!=='table'">${['text','textarea','number','date','select','inspection','table','photo'].map(type=>`<option ${f.type===type?'selected':''}>${type}</option>`).join('')}</select></div><div class="field"><label for="field-unit">Measurement unit (optional)</label><input id="field-unit" value="${E(f.unit||'')}" placeholder="m, V, A, Ah, °"></div></div><div id="field-options-wrap" class="field" style="margin-top:17px" ${f.type==='select'?'':'hidden'}><label for="field-options">Dropdown choices, one per line</label><textarea id="field-options">${E((f.options||['Yes','No','Not applicable']).join('\n'))}</textarea></div><div id="field-columns-wrap" class="field" style="margin-top:17px" ${f.type==='table'?'':'hidden'}><label for="field-columns">Table column labels, one per line</label><textarea id="field-columns">${E((f.columns||[{label:'Value'}]).map(c=>c.label).join('\n'))}</textarea></div><label class="checkitem" style="margin-top:17px"><input id="field-required" type="checkbox" ${f.required?'checked':''}><span>Required before submission</span></label>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="commitBuilderField(${i})">${i<0?'Add field':'Save field'}</button>`)}
function commitBuilderField(i){if(!canEditTemplate())return;const label=document.getElementById('field-label').value.trim(),type=document.getElementById('field-type').value;if(!label){toast('Enter a field label');return}const fields=currentTemplate().definition.sections[builderSection].fields,existing=i<0?null:fields[i];const f={...(existing||{}),id:existing?.id||'field_'+crypto.randomUUID().replaceAll('-','').slice(0,12),label,type,required:document.getElementById('field-required').checked,unit:document.getElementById('field-unit').value.trim()};if(type==='select'){f.options=document.getElementById('field-options').value.split('\n').map(x=>x.trim()).filter(Boolean);if(!f.options.length){toast('Enter at least one dropdown choice');return}}if(type==='table'){f.columns=document.getElementById('field-columns').value.split('\n').map(x=>x.trim()).filter(Boolean).map((v,j)=>({id:existing?.columns?.[j]?.id||'column_'+j,label:v}));if(!f.columns.length){toast('Enter at least one table column');return}}if(existing)fields[i]=f;else fields.push(f);persist();closeModal();render()}
function bindTemplateToSite(s,t){s.templateSnapshot=cloneTemplateValue(t);s.customAnswers={};s.templateSnapshot.definition.sections.flatMap(x=>x.fields).filter(f=>f.system==='site_id').forEach(f=>s.customAnswers[f.id]=s.id)}
function tryTemplate(){const t=currentTemplate();if(!t.published){toast('Publish the template before starting a sample survey');return}const s=cloneTemplateValue(seeds()[0]);s.id='DEMO-CUSTOM-'+(data.sites.filter(x=>x.id.startsWith('DEMO-CUSTOM-')).length+1);s.status='Draft';s.progress=0;s.photos=[];s.comments=[];s.answers.siteName=s.id;bindTemplateToSite(s,t);data.sites.unshift(s);persist();customSection=0;openSite(s.id)}
function customMissing(s){const answers=s.customAnswers||{};return s.templateSnapshot.definition.sections.flatMap(x=>x.fields).filter(f=>f.required).filter(f=>{let v=f.system==='site_id'?s.id:answers[f.id];if(f.type==='photo')return !s.photos.some(p=>p.fieldId===f.id);if(f.type==='inspection')return !v?.result||(v.result==='Not applicable'&&!v.remarks?.trim());if(f.type==='table')return !Array.isArray(v)||!v.some(r=>Object.values(r).some(x=>String(x).trim()));return !String(v??'').trim()}).map(f=>f.label)}
function customProgress(s){const fields=s.templateSnapshot.definition.sections.flatMap(x=>x.fields),answers=s.customAnswers||{};if(!fields.length)return 0;const completed=fields.filter(f=>{if(f.system==='site_id')return !!s.id;if(f.type==='photo')return s.photos.some(p=>p.fieldId===f.id);const v=answers[f.id];if(f.type==='inspection')return !!v?.result&&(v.result!=='Not applicable'||!!v.remarks?.trim());if(f.type==='table')return Array.isArray(v)&&v.some(r=>Object.values(r).some(x=>String(x).trim()));return String(v??'').trim()!==''}).length;return Math.round(completed/fields.length*100)}

function customWorkspacePage(s){const t=s.templateSnapshot,all=t.definition.sections;customSection=Math.min(customSection,all.length);const current=all[customSection],locked=s.status==='Approved';return `<button class="back" onclick="go('sites')">${I('back')}Back to sites</button><section class="card custom-survey-header">${clientLogos(t.clients)}<div><h1>${E(s.id)}</h1><p>${E(t.name)} · v${t.version}</p></div>${badge(s.status)}</section><div class="custom-workspace"><aside class="card custom-section-list"><p class="eyebrow muted" style="padding:15px 12px 10px">CHECKLIST SECTIONS</p>${all.map((sec,i)=>`<button class="${i===customSection?'active':''}" onclick="customSection=${i};render()"><span>${i+1}.</span><span>${E(sec.title)}</span><small>${sec.fields.length}</small></button>`).join('')}<button class="${customSection===all.length?'active':''}" onclick="customSection=${all.length};render()">${I('shield')}Review & submit</button></aside><section class="card"><div class="card-head"><div><h2>${E(current?.title||'Review & submit')}</h2><p>${current?'Section '+(customSection+1)+' of '+all.length+' · '+current.fields.length+' fields':'Your original submission and approval workflow'}</p></div><span id="save-state" class="save-state">${I(locked?'shield':'check')}${locked?'Approved · locked':'Saved on this device'}</span></div><div class="form-body">${current?current.fields.map(f=>customFieldMarkup(s,f,locked)).join(''):customSubmission(s)}</div><div class="form-foot"><button class="btn" ${customSection===0?'disabled':''} onclick="customSection--;render()">${I('back')}Back</button><span class="small muted">${E(t.name)} · v${t.version}</span><button class="btn primary" onclick="${customSection===all.length?"go('overview')":"customSection++;render()"}">${customSection===all.length?'Overview':'Next section'}${I('arrow')}</button></div></section></div>`}
function customFieldMarkup(s,f,locked){const v=f.system==='site_id'?s.id:(s.customAnswers||{})[f.id],id=E(f.id),disabled=locked?'disabled':'',on=`saveCustomAnswer('${id}',this.value)`;let input='';if(f.type==='inspection')input=`<select aria-label="Inspection result" ${disabled} onchange="saveCustomInspection('${id}','result',this.value)"><option value="">Choose result</option>${['Checked','Defect found','Not applicable'].map(o=>`<option ${v?.result===o?'selected':''}>${o}</option>`).join('')}</select><textarea aria-label="Observations" placeholder="Observations / reason for not applicable" style="margin-top:9px" ${locked?'readonly':''} oninput="saveCustomInspection('${id}','remarks',this.value)">${E(v?.remarks||'')}</textarea>`;else if(f.type==='select')input=`<select id="cf-${id}" ${disabled} onchange="${on}"><option value="">Choose an option</option>${(f.options||[]).map(o=>`<option ${v===o?'selected':''}>${E(o)}</option>`).join('')}</select>`;else if(f.type==='textarea')input=`<textarea id="cf-${id}" ${locked?'readonly':''} oninput="${on}">${E(v||'')}</textarea>`;else if(f.type==='table'){const rows=Array.isArray(v)?v:[];input=`<div class="table-wrap"><table class="custom-inventory"><thead><tr>${f.columns.map(c=>`<th>${E(c.label)}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map((r,i)=>`<tr>${f.columns.map(c=>`<td><input aria-label="${E(c.label)}" value="${E(r[c.id]||'')}" ${locked?'readonly':''} oninput="saveCustomTableCell('${id}',${i},'${E(c.id)}',this.value)"></td>`).join('')}<td>${locked?'':`<button class="iconbtn" aria-label="Remove equipment row" onclick="removeCustomTableRow('${id}',${i})">${I('trash')}</button>`}</td></tr>`).join('')}</tbody></table></div>${locked?'':`<button class="btn" style="margin-top:10px" onclick="addCustomTableRow('${id}')">${I('plus')}Add row</button>`}`;}else if(f.type!=='photo')input=`<input id="cf-${id}" type="${f.type==='number'?'number':f.type==='date'?'date':'text'}" ${f.type==='number'?'step="any"':''} value="${E(v??'')}" ${locked||f.system?'readonly':''} oninput="${on}">`;const photos=s.photos.map((p,i)=>({p,i})).filter(x=>x.p.fieldId===f.id);return `<div class="custom-field-preview field"><label for="cf-${id}">${E(f.label)}${f.required?' <span class="builder-required">*</span>':''}${f.unit?' ('+E(f.unit)+')':''}</label>${input}${['photo','inspection'].includes(f.type)?`${locked?'':`<button class="btn" style="margin-top:12px" onclick="window.customEvidenceField='${id}';uploadForSite()">${I('camera')}Add evidence</button>`}<div class="photo-grid">${photos.map(x=>photoCard(s,x.p,x.i)).join('')}</div>`:''}</div>`}
function saveCustomAnswer(fid,value){const s=site();if(s.status==='Approved')return;const f=s.templateSnapshot.definition.sections.flatMap(x=>x.fields).find(f=>f.id===fid);if(!f||f.system)return;s.customAnswers=s.customAnswers||{};s.customAnswers[fid]=value;s.progress=customProgress(s);if(s.status==='Draft')s.status='In progress';saveChanges()}
function saveCustomInspection(fid,key,value){const previous=(site().customAnswers||{})[fid]||{};saveCustomAnswer(fid,{...previous,[key]:value})}
function addCustomTableRow(fid){const rows=cloneTemplateValue((site().customAnswers||{})[fid]||[]);rows.push({});saveCustomAnswer(fid,rows);render()}
function removeCustomTableRow(fid,i){const rows=cloneTemplateValue((site().customAnswers||{})[fid]||[]);rows.splice(i,1);saveCustomAnswer(fid,rows);render()}
function saveCustomTableCell(fid,i,key,value){const rows=cloneTemplateValue((site().customAnswers||{})[fid]||[]);rows[i][key]=value;saveCustomAnswer(fid,rows)}
function customSubmission(s){const missing=customMissing(s),t=s.templateSnapshot;return `<div class="builder-brand-preview">${clientLogos(t.clients)}<strong>${E(t.name)} · v${t.version}</strong></div><div class="statline"><span>Configured sections</span><b>${t.definition.sections.length}</b></div><div class="statline"><span>Configured fields</span><b>${fieldCount(t)}</b></div><div class="statline"><span>Uploaded photographs</span><b>${s.photos.length}</b></div><div class="statline"><span>Required fields pending</span><b>${missing.length}</b></div>${missing.length?`<p class="form-intro">Complete: ${missing.map(E).join(' · ')}</p>`:'<p class="form-intro">Required information is complete. Review your survey before submission.</p>'}<div class="row wrap" style="margin-top:20px"><button class="btn" onclick="downloadReport('${E(s.id)}')">${I('export')}Export CSV</button><button class="btn" onclick="printReport()">${I('file')}Print report</button>${s.status==='Approved'?'<span class="tag green">Approved record · locked</span>':s.status==='Awaiting review'&&role!=='Engineer'?`<button class="btn primary" onclick="reviewSite('${E(s.id)}','approve')">Review decision</button>`:`<button class="btn primary" ${missing.length?'disabled':''} onclick="submitSite()">Submit for review ${I('arrow')}</button>`}</div>${s.comments.length?`<h3 style="margin-top:27px">Review feedback</h3>${s.comments.map(c=>`<p class="form-intro"><strong>${E(c.by)}</strong><br>${E(c.text)}</p>`).join('')}`:''}`}
function downloadCustomReport(s){const t=s.templateSnapshot,answers=s.customAnswers||{};const rows=[['Section','Field','Value'],['Record','Site ID',s.id],['Record','Checklist',t.name],['Record','Revision',t.version],['Record','Status',s.status],...t.clients.map((c,i)=>['Client branding','Client '+(i+1),c.name])];for(const sec of t.definition.sections)for(const f of sec.fields){let value=f.system==='site_id'?s.id:answers[f.id];if(f.type==='table'){for(const row of value||[])rows.push([sec.title,f.label,f.columns.map(c=>c.label+': '+(row[c.id]||'')).join(' | ')])}else rows.push([sec.title,f.label,typeof value==='object'?JSON.stringify(value):value||'']);for(const p of s.photos.filter(p=>p.fieldId===f.id))rows.push([sec.title,'Evidence: '+f.label,p.name])}for(const c of s.comments)rows.push(['Review',c.by,c.text]);downloadCSV(s.id+'-custom-survey.csv',rows)}
function printCustomReport(s){const t=s.templateSnapshot,answers=s.customAnswers||{};const w=window.open('','_blank');if(!w){toast('Allow pop-ups to open the report');return}w.document.write(`<!doctype html><html><head><title>${E(s.id)} survey</title><style>body{font:12px Arial;color:#24351b;padding:35px}h1{font-size:22px}h2{font-size:16px;margin-top:28px}table{width:100%;border-collapse:collapse}td{padding:10px;border:1px solid #ddd;vertical-align:top}img{max-width:220px;max-height:150px}.client-branding{display:flex;justify-content:space-between;align-items:center}.client-branding img{max-width:150px;max-height:60px}.client-branding span{display:block;margin-top:7px}button{padding:12px 20px;margin-top:25px}@media print{button{display:none}.field{break-inside:avoid}}</style></head><body>${clientLogos(t.clients)}<h1>${E(t.name)}</h1><p>Site ${E(s.id)} · Revision ${t.version} · ${E(s.status)}</p><p>Design preview · sample data</p>${t.definition.sections.map(sec=>`<h2>${E(sec.title)}</h2>${sec.fields.map(f=>{const value=f.system==='site_id'?s.id:answers[f.id];return `<div class="field"><table><tr><td style="width:45%">${E(f.label)}</td><td>${E(typeof value==='object'?JSON.stringify(value):value||'—')}</td></tr></table>${s.photos.filter(p=>p.fieldId===f.id).map(p=>`<img src="${E(p.src)}" alt="${E(p.name)}">`).join('')}</div>`}).join('')}`).join('')}<h2>Review comments</h2>${s.comments.map(c=>`<p>${E(c.by)}: ${E(c.text)}</p>`).join('')}<button onclick="window.print()">Print / Save PDF</button></body></html>`);w.document.close();w.focus()}
initTemplateData();
if(typeof location !== 'undefined' && location.hash === '#builder'){role='Admin';view='builder';}
render();
